def run(command: str, **kwargs: Any) -> Result:
    try:
        process = subprocess.run(command, capture_output=True, text=True, shell=True, **kwargs)
        return Result(process.stdout, process.stderr, process.returncode)
    except Exception as e:
        print(f"An error occurred: {e}")
